"use client";

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import {
  UploadCloud,
  FileText,
  AlertTriangle,
  CheckCircle,
  Clock,
  Shield,
  Activity,
  ChevronRight,
  Download,
  Search,
  Filter,
  LogOut,
  User as UserIcon,
  Check
} from 'lucide-react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar
} from 'recharts';

const API_BASE = 'http://localhost:8000';

export default function MetroScanDashboard() {
  const [token, setToken] = useState(null);
  const [user, setUser] = useState(null); // { sub: email, role: role }
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [loginError, setLoginError] = useState('');

  const [activeTab, setActiveTab] = useState('dashboard');
  
  const [stats, setStats] = useState({
    total_scanned: 0,
    compliance_rate: 0,
    violations_by_rule: {},
    needs_review_count: 0,
    likely_violation_count: 0
  });
  
  const [inspections, setInspections] = useState([]);
  const [selectedInspection, setSelectedInspection] = useState(null);
  
  const [uploadFile, setUploadFile] = useState(null);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadMode, setUploadMode] = useState('single');

  // Setup Axios interceptor
  useEffect(() => {
    if (token) {
      axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
      fetchStats();
      fetchInspections();
    } else {
      delete axios.defaults.headers.common['Authorization'];
    }
  }, [token]);

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoginError('');
    try {
      const formData = new URLSearchParams();
      formData.append('username', loginEmail);
      formData.append('password', loginPassword);
      
      const res = await axios.post(`${API_BASE}/token`, formData, {
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
      });
      
      const accessToken = res.data.access_token;
      setToken(accessToken);
      
      // Decode JWT
      const base64Url = accessToken.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const payload = JSON.parse(window.atob(base64));
      setUser(payload);
      
      if (payload.role === 'Supervisor') {
        setActiveTab('inspections'); // Supervisors default to inspections since they can't upload
      }
    } catch (e) {
      setLoginError('Invalid credentials');
    }
  };

  const handleLogout = () => {
    setToken(null);
    setUser(null);
    setActiveTab('dashboard');
  };

  const fetchStats = async () => {
    try {
      const res = await axios.get(`${API_BASE}/dashboard/stats`);
      setStats(res.data);
    } catch (e) {
      console.error(e);
    }
  };

  const fetchInspections = async () => {
    try {
      const res = await axios.get(`${API_BASE}/inspections`);
      setInspections(res.data);
    } catch (e) {
      console.error(e);
    }
  };

  const handleUpload = async () => {
    if (!uploadFile) return;
    setIsUploading(true);
    
    const formData = new FormData();
    formData.append('file', uploadFile);
    
    try {
      if (uploadMode === 'single') {
        formData.append('product_name', 'Uploaded Product');
        formData.append('brand_name', 'Uploaded Brand');
        await axios.post(`${API_BASE}/scan/single`, formData);
      } else {
        await axios.post(`${API_BASE}/scan/bulk`, formData);
      }
      await fetchStats();
      await fetchInspections();
      setActiveTab('inspections');
    } catch (e) {
      console.error(e);
      alert('Upload failed: ' + (e.response?.data?.detail || e.message));
    } finally {
      setIsUploading(false);
      setUploadFile(null);
    }
  };

  const handleExport = (id, format) => {
    window.open(`${API_BASE}/inspections/${id}/export?format=${format}&token=${token}`, '_blank');
  };

  const handleSignOff = async (id) => {
    try {
      await axios.post(`${API_BASE}/inspections/${id}/sign-off`);
      alert("Violation signed off and confirmed.");
      fetchInspections();
      fetchStats();
      setSelectedInspection({...selectedInspection, verdict: 'Likely Violation'});
    } catch (e) {
      alert("Sign-off failed.");
    }
  };

  // Login Screen
  if (!token) {
    return (
      <div className="min-h-screen bg-[#0f172a] text-slate-200 flex items-center justify-center p-4">
        <div className="max-w-md w-full bg-slate-900/60 backdrop-blur-xl border border-slate-800 rounded-3xl p-8 shadow-2xl">
          <div className="flex items-center justify-center mb-8">
            <div className="w-12 h-12 rounded-xl bg-gradient-to-tr from-blue-600 to-indigo-400 flex items-center justify-center shadow-lg shadow-blue-500/20 mr-4">
              <Shield className="w-7 h-7 text-white" />
            </div>
            <div>
              <h1 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">METROSCAN AI</h1>
              <p className="text-xs text-blue-400 font-medium">Compliance Intelligence</p>
            </div>
          </div>
          
          <form onSubmit={handleLogin} className="space-y-6">
            <div>
              <label className="text-sm font-medium text-slate-400 mb-1 block">Email Address</label>
              <input 
                type="email" 
                value={loginEmail} 
                onChange={(e) => setLoginEmail(e.target.value)} 
                className="w-full bg-slate-800/50 border border-slate-700 text-white rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none" 
                placeholder="officer@doca.gov.in" 
                required 
              />
            </div>
            <div>
              <label className="text-sm font-medium text-slate-400 mb-1 block">Password</label>
              <input 
                type="password" 
                value={loginPassword} 
                onChange={(e) => setLoginPassword(e.target.value)} 
                className="w-full bg-slate-800/50 border border-slate-700 text-white rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none" 
                placeholder="••••••••" 
                required 
              />
            </div>
            {loginError && <p className="text-rose-400 text-sm">{loginError}</p>}
            <button type="submit" className="w-full bg-blue-600 hover:bg-blue-500 text-white font-semibold py-3 rounded-xl shadow-lg transition-colors">
              Sign In
            </button>
          </form>
          
          <div className="mt-8 text-center text-xs text-slate-500 space-y-1">
            <p>Demo Accounts (Password: Pass@123)</p>
            <p>inspector@doca.gov.in (Upload/Export)</p>
            <p>supervisor@doca.gov.in (Review/Sign-off)</p>
            <p>admin@doca.gov.in (Full Access)</p>
          </div>
        </div>
      </div>
    );
  }

  // UI Components
  const TabButton = ({ id, label, icon: Icon, hidden }) => {
    if (hidden) return null;
    return (
      <button
        onClick={() => setActiveTab(id)}
        className={`flex w-full items-center px-4 py-3 rounded-xl transition-all duration-300 font-medium ${
          activeTab === id 
            ? 'bg-gradient-to-r from-blue-600 to-indigo-600 text-white shadow-lg shadow-blue-500/30' 
            : 'text-slate-400 hover:text-white hover:bg-slate-800/50'
        }`}
      >
        <Icon className="w-5 h-5 mr-3" />
        {label}
      </button>
    );
  };

  const StatCard = ({ title, value, subtitle, icon: Icon, colorClass }) => (
    <div className="bg-slate-900/60 backdrop-blur-xl border border-slate-800 p-6 rounded-2xl relative overflow-hidden group hover:border-slate-700 transition-all duration-300">
      <div className={`absolute top-0 right-0 w-32 h-32 opacity-10 rounded-bl-full bg-gradient-to-bl ${colorClass}`}></div>
      <div className="flex items-center justify-between relative z-10">
        <div>
          <p className="text-slate-400 text-sm font-medium mb-1">{title}</p>
          <h3 className="text-3xl font-bold text-white tracking-tight">{value}</h3>
          <p className="text-slate-500 text-xs mt-2">{subtitle}</p>
        </div>
        <div className={`p-4 rounded-xl bg-gradient-to-br ${colorClass} bg-opacity-10 backdrop-blur-sm`}>
          <Icon className="w-6 h-6 text-white" />
        </div>
      </div>
    </div>
  );

  const canUpload = user?.role === 'Inspector' || user?.role === 'Admin';
  const canSignOff = user?.role === 'Supervisor' || user?.role === 'Admin';

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-200 font-sans selection:bg-blue-500/30">
      <div className="flex h-screen overflow-hidden">
        
        {/* Sidebar */}
        <div className="w-72 border-r border-slate-800/60 bg-slate-900/40 backdrop-blur-2xl flex flex-col justify-between">
          <div>
            <div className="p-8">
              <div className="flex items-center">
                <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-blue-600 to-indigo-400 flex items-center justify-center shadow-lg shadow-blue-500/20 mr-3">
                  <Shield className="w-6 h-6 text-white" />
                </div>
                <div>
                  <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400 tracking-tight">METROSCAN AI</h1>
                  <p className="text-xs text-blue-400 font-medium">Compliance Intelligence</p>
                </div>
              </div>
            </div>
            
            <nav className="px-4 space-y-2 mt-4">
              <TabButton id="dashboard" label="Dashboard" icon={Activity} />
              <TabButton id="upload" label="Upload & Scan" icon={UploadCloud} hidden={!canUpload} />
              <TabButton id="inspections" label="Inspections" icon={FileText} />
            </nav>
          </div>
        </div>

        {/* Main Content */}
        <div className="flex-1 overflow-y-auto scrollbar-hide flex flex-col">
          <header className="sticky top-0 z-40 bg-slate-900/80 backdrop-blur-xl border-b border-slate-800/60 px-10 py-4 flex justify-between items-center shrink-0">
            <h2 className="text-2xl font-bold text-white tracking-tight capitalize">{activeTab.replace('-', ' ')}</h2>
            
            <div className="flex items-center space-x-6">
              <div className="text-sm text-slate-400 flex items-center"><span className="w-2 h-2 rounded-full bg-emerald-500 inline-block mr-2 animate-pulse"></span>System Active</div>
              
              <div className="h-6 w-px bg-slate-800"></div>
              
              {/* Profile Badge */}
              <div className="flex items-center bg-slate-800/50 border border-slate-700/50 rounded-full pl-2 pr-4 py-1.5">
                <div className="w-7 h-7 bg-indigo-500/20 text-indigo-400 rounded-full flex items-center justify-center mr-3">
                  <UserIcon className="w-4 h-4" />
                </div>
                <div className="mr-4">
                  <p className="text-sm font-semibold text-white leading-tight">{user?.sub.split('@')[0]}</p>
                  <p className="text-[10px] text-blue-400 uppercase tracking-wider">{user?.role}</p>
                </div>
                <button onClick={handleLogout} className="text-slate-400 hover:text-rose-400 transition-colors p-1" title="Logout">
                  <LogOut className="w-4 h-4" />
                </button>
              </div>
            </div>
          </header>

          <main className="p-10 max-w-7xl mx-auto w-full flex-1">
            
            {activeTab === 'dashboard' && (
              <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                  <StatCard 
                    title="Total Scanned" 
                    value={stats.total_scanned} 
                    subtitle="All time inspections" 
                    icon={Activity} 
                    colorClass="from-blue-500 to-indigo-600"
                  />
                  <StatCard 
                    title="Compliance Rate" 
                    value={`${(stats.compliance_rate * 100).toFixed(1)}%`} 
                    subtitle="Fully compliant products" 
                    icon={CheckCircle} 
                    colorClass="from-emerald-400 to-emerald-600"
                  />
                  <StatCard 
                    title="Needs Review" 
                    value={stats.needs_review_count} 
                    subtitle="Requires officer attention" 
                    icon={Clock} 
                    colorClass="from-amber-400 to-amber-600"
                  />
                  <StatCard 
                    title="Violations" 
                    value={stats.likely_violation_count} 
                    subtitle="Likely violations detected" 
                    icon={AlertTriangle} 
                    colorClass="from-rose-500 to-rose-700"
                  />
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                  <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6">
                    <h3 className="text-lg font-bold text-white mb-6">Violation Frequency by Rule</h3>
                    <div className="h-64">
                      {Object.keys(stats.violations_by_rule).length > 0 ? (
                        <ResponsiveContainer width="100%" height="100%">
                          <BarChart data={Object.entries(stats.violations_by_rule).map(([k,v]) => ({name: k, value: v}))}>
                            <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                            <XAxis dataKey="name" stroke="#64748b" tick={{fontSize: 12}} />
                            <YAxis stroke="#64748b" />
                            <Tooltip contentStyle={{backgroundColor: '#0f172a', borderColor: '#1e293b', borderRadius: '8px'}} />
                            <Bar dataKey="value" fill="#3b82f6" radius={[4, 4, 0, 0]} />
                          </BarChart>
                        </ResponsiveContainer>
                      ) : (
                        <div className="h-full flex items-center justify-center text-slate-500">No violations data</div>
                      )}
                    </div>
                  </div>
                  
                  <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6">
                    <h3 className="text-lg font-bold text-white mb-6">Recent Activity Trend</h3>
                    <div className="h-64 flex items-center justify-center text-slate-500">
                      <ResponsiveContainer width="100%" height="100%">
                        <LineChart data={[
                          { name: 'Mon', count: 4 },
                          { name: 'Tue', count: 7 },
                          { name: 'Wed', count: 3 },
                          { name: 'Thu', count: 8 },
                          { name: 'Fri', count: stats.total_scanned }
                        ]}>
                          <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                          <XAxis dataKey="name" stroke="#64748b" />
                          <YAxis stroke="#64748b" />
                          <Tooltip contentStyle={{backgroundColor: '#0f172a', borderColor: '#1e293b', borderRadius: '8px'}} />
                          <Line type="monotone" dataKey="count" stroke="#10b981" strokeWidth={3} dot={{r: 4, strokeWidth: 2}} />
                        </LineChart>
                      </ResponsiveContainer>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'upload' && canUpload && (
              <div className="max-w-2xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-700">
                <div className="bg-slate-900/60 border border-slate-800 rounded-3xl p-8 backdrop-blur-xl shadow-2xl">
                  <div className="text-center mb-8">
                    <div className="w-16 h-16 bg-blue-500/10 rounded-full flex items-center justify-center mx-auto mb-4 text-blue-400">
                      <UploadCloud className="w-8 h-8" />
                    </div>
                    <h3 className="text-2xl font-bold text-white mb-2">Upload for Inspection</h3>
                    <p className="text-slate-400">Scan product labels instantly using our AI OCR engine.</p>
                  </div>
                  
                  <div className="flex bg-slate-800/50 p-1 rounded-xl mb-8">
                    <button 
                      onClick={() => setUploadMode('single')}
                      className={`flex-1 py-2.5 rounded-lg text-sm font-medium transition-all ${uploadMode === 'single' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-400 hover:text-slate-300'}`}
                    >
                      Single Image
                    </button>
                    <button 
                      onClick={() => setUploadMode('bulk')}
                      className={`flex-1 py-2.5 rounded-lg text-sm font-medium transition-all ${uploadMode === 'bulk' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-400 hover:text-slate-300'}`}
                    >
                      Bulk CSV
                    </button>
                  </div>

                  <div className="border-2 border-dashed border-slate-700 rounded-2xl p-10 flex flex-col items-center justify-center text-center hover:border-blue-500/50 hover:bg-slate-800/30 transition-all cursor-pointer group relative overflow-hidden">
                    <input 
                      type="file" 
                      className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" 
                      onChange={(e) => setUploadFile(e.target.files[0])}
                      accept={uploadMode === 'single' ? 'image/*' : '.csv'}
                    />
                    <UploadCloud className="w-10 h-10 text-slate-500 group-hover:text-blue-400 transition-colors mb-4" />
                    <p className="text-white font-medium mb-1">
                      {uploadFile ? uploadFile.name : `Drag and drop or click to select ${uploadMode === 'single' ? 'an image' : 'a CSV'}`}
                    </p>
                    <p className="text-slate-500 text-sm">
                      {uploadMode === 'single' ? 'PNG, JPG up to 10MB' : 'CSV containing image paths'}
                    </p>
                  </div>

                  <button 
                    onClick={handleUpload}
                    disabled={!uploadFile || isUploading}
                    className="w-full mt-8 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-semibold py-4 rounded-xl shadow-lg shadow-blue-500/25 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex justify-center items-center"
                  >
                    {isUploading ? (
                      <><div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin mr-3"></div> Processing...</>
                    ) : 'Start Analysis'}
                  </button>
                </div>
              </div>
            )}

            {activeTab === 'inspections' && !selectedInspection && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
                <div className="bg-slate-900/60 border border-slate-800 rounded-2xl overflow-hidden backdrop-blur-xl">
                  <div className="p-6 border-b border-slate-800/60 flex justify-between items-center">
                    <div className="relative w-72">
                      <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
                      <input type="text" placeholder="Search inspections..." className="w-full bg-slate-800/50 border border-slate-700 text-sm text-slate-300 rounded-lg pl-9 pr-4 py-2 focus:ring-2 focus:ring-blue-500 outline-none" />
                    </div>
                    <button className="p-2 border border-slate-700 text-slate-400 rounded-lg hover:bg-slate-800"><Filter className="w-4 h-4" /></button>
                  </div>
                  
                  <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                      <thead>
                        <tr className="bg-slate-900 text-slate-400 text-xs uppercase tracking-wider border-b border-slate-800/60">
                          <th className="p-4 font-semibold">Date / ID</th>
                          <th className="p-4 font-semibold">Product</th>
                          <th className="p-4 font-semibold">Verdict</th>
                          <th className="p-4 font-semibold">Confidence</th>
                          <th className="p-4 font-semibold">Action</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-800/60">
                        {inspections.map((insp) => (
                          <tr key={insp.id} className="hover:bg-slate-800/30 transition-colors cursor-pointer" onClick={() => setSelectedInspection(insp)}>
                            <td className="p-4">
                              <p className="text-white font-medium">{new Date(insp.created_at).toLocaleDateString()}</p>
                              <p className="text-xs text-slate-500 font-mono mt-1">{insp.id.substring(0,8)}</p>
                            </td>
                            <td className="p-4">
                              <p className="text-slate-300 font-medium">{insp.product_name || 'Unknown'}</p>
                              <p className="text-xs text-slate-500">{insp.brand_name}</p>
                            </td>
                            <td className="p-4">
                              <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-medium border ${
                                insp.verdict === 'Likely Compliant' ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' :
                                insp.verdict === 'Needs Officer Review' ? 'bg-amber-500/10 text-amber-400 border-amber-500/20' :
                                'bg-rose-500/10 text-rose-400 border-rose-500/20'
                              }`}>
                                {insp.verdict === 'Likely Compliant' && <CheckCircle className="w-3 h-3 mr-1.5" />}
                                {insp.verdict === 'Needs Officer Review' && <Clock className="w-3 h-3 mr-1.5" />}
                                {insp.verdict === 'Likely Violation' && <AlertTriangle className="w-3 h-3 mr-1.5" />}
                                {insp.verdict}
                              </span>
                            </td>
                            <td className="p-4">
                              <div className="flex items-center">
                                <div className="w-16 h-1.5 bg-slate-800 rounded-full mr-3 overflow-hidden">
                                  <div className={`h-full rounded-full ${insp.ocr_confidence > 0.7 ? 'bg-emerald-500' : 'bg-amber-500'}`} style={{width: `${insp.ocr_confidence * 100}%`}}></div>
                                </div>
                                <span className="text-xs text-slate-400">{(insp.ocr_confidence * 100).toFixed(0)}%</span>
                              </div>
                            </td>
                            <td className="p-4">
                              <button className="text-blue-400 hover:text-blue-300 text-sm font-medium flex items-center">
                                View <ChevronRight className="w-4 h-4 ml-1" />
                              </button>
                            </td>
                          </tr>
                        ))}
                        {inspections.length === 0 && (
                          <tr><td colSpan="5" className="p-8 text-center text-slate-500">No inspections found.</td></tr>
                        )}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'inspections' && selectedInspection && (
              <div className="animate-in slide-in-from-right-8 duration-500">
                <button 
                  onClick={() => setSelectedInspection(null)}
                  className="mb-6 text-slate-400 hover:text-white flex items-center text-sm font-medium transition-colors"
                >
                  <ChevronRight className="w-4 h-4 mr-1 rotate-180" /> Back to List
                </button>
                
                <div className="flex justify-between items-start mb-6">
                  <div>
                    <h2 className="text-3xl font-bold text-white mb-2">{selectedInspection.product_name || 'Inspection Details'}</h2>
                    <p className="text-slate-400 font-mono text-sm">ID: {selectedInspection.id}</p>
                  </div>
                  <div className="flex space-x-3">
                    {canSignOff && selectedInspection.verdict === 'Needs Officer Review' && (
                      <button onClick={() => handleSignOff(selectedInspection.id)} className="flex items-center px-4 py-2 bg-rose-600 hover:bg-rose-500 text-white rounded-lg text-sm font-medium transition-colors shadow-lg shadow-rose-500/20">
                        <Check className="w-4 h-4 mr-2" /> Sign Off Violation
                      </button>
                    )}
                    <button onClick={() => handleExport(selectedInspection.id, 'pdf')} className="flex items-center px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-lg text-sm font-medium transition-colors border border-slate-700">
                      <Download className="w-4 h-4 mr-2" /> PDF Memo
                    </button>
                    <button onClick={() => handleExport(selectedInspection.id, 'docx')} className="flex items-center px-4 py-2 bg-blue-600/20 hover:bg-blue-600/30 text-blue-400 rounded-lg text-sm font-medium transition-colors border border-blue-500/20">
                      <Download className="w-4 h-4 mr-2" /> DOCX
                    </button>
                  </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                  <div className="lg:col-span-1">
                    <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-4 sticky top-24">
                      <div className="aspect-[4/3] bg-slate-800 rounded-xl mb-4 relative overflow-hidden group">
                        <img src={`http://localhost:8000/${selectedInspection.image_path}`} alt="Label" className="w-full h-full object-contain opacity-80 group-hover:opacity-100 transition-opacity" onError={(e) => { e.target.src = "https://via.placeholder.com/800x600?text=Image+Unavailable"; }} />
                        
                        {selectedInspection.raw_ocr_json.bboxes && selectedInspection.raw_ocr_json.bboxes.map((box, i) => (
                           <div key={i} className="absolute border border-blue-500 bg-blue-500/10 pointer-events-none" style={{
                             left: `${box.x / 8}%`, 
                             top: `${box.y / 6}%`,
                             width: `${box.w / 8}%`,
                             height: `${box.h / 6}%`
                           }}></div>
                        ))}
                      </div>
                      <div className={`p-4 rounded-xl border flex items-start ${
                        selectedInspection.verdict === 'Likely Compliant' ? 'bg-emerald-500/10 border-emerald-500/20' :
                        selectedInspection.verdict === 'Needs Officer Review' ? 'bg-amber-500/10 border-amber-500/20' :
                        'bg-rose-500/10 border-rose-500/20'
                      }`}>
                        {selectedInspection.verdict === 'Likely Compliant' && <CheckCircle className="w-6 h-6 text-emerald-400 mr-3 shrink-0" />}
                        {selectedInspection.verdict === 'Needs Officer Review' && <Clock className="w-6 h-6 text-amber-400 mr-3 shrink-0" />}
                        {selectedInspection.verdict === 'Likely Violation' && <AlertTriangle className="w-6 h-6 text-rose-400 mr-3 shrink-0" />}
                        
                        <div>
                          <h4 className={`font-bold ${
                            selectedInspection.verdict === 'Likely Compliant' ? 'text-emerald-400' :
                            selectedInspection.verdict === 'Needs Officer Review' ? 'text-amber-400' :
                            'text-rose-400'
                          }`}>{selectedInspection.verdict}</h4>
                          <p className="text-xs text-slate-400 mt-1">OCR Confidence: {(selectedInspection.ocr_confidence * 100).toFixed(1)}%</p>
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="lg:col-span-2 space-y-6">
                    <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6">
                      <h3 className="text-lg font-bold text-white mb-4">Extracted Fields</h3>
                      <div className="grid grid-cols-2 gap-4">
                        {Object.entries(selectedInspection.extracted_fields_json).map(([k, v]) => (
                          <div key={k} className="bg-slate-800/50 rounded-lg p-3 border border-slate-700/50">
                            <span className="text-xs text-slate-500 uppercase tracking-wider font-semibold block mb-1">{k.replace('_', ' ')}</span>
                            <span className="text-slate-200 font-medium">{v || <span className="text-slate-600 italic">Not detected</span>}</span>
                          </div>
                        ))}
                      </div>
                    </div>

                    <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6">
                      <h3 className="text-lg font-bold text-white mb-4">Rule Engine Verdicts</h3>
                      <div className="space-y-3">
                        {selectedInspection.rule_results_json.map((res, i) => (
                          <div key={i} className="bg-slate-800/50 border border-slate-700/50 rounded-xl p-4 flex items-start">
                            <div className="mr-4 mt-0.5">
                              {res.status === 'Likely Compliant' ? <CheckCircle className="w-5 h-5 text-emerald-500" /> :
                               res.status === 'Needs Officer Review' ? <Clock className="w-5 h-5 text-amber-500" /> :
                               <AlertTriangle className="w-5 h-5 text-rose-500" />}
                            </div>
                            <div>
                              <h4 className="text-white font-medium">{res.rule}</h4>
                              <p className="text-slate-400 text-sm mt-1">{res.message}</p>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}

          </main>
        </div>
      </div>
    </div>
  );
}
